using Microsoft.CodeAnalysis;
using Xui.Compiler.Tests.Wasm.Canvas;
using Xui.Compiler.WASM.Emitter;
using Xunit;

namespace Xui.Compiler.Tests.Wasm.TestApp;

public class MobileReadinessTests(Xunit.Abstractions.ITestOutputHelper output)
{
    [Fact]
    public void FullMobileShellReportsRemainingCompilerGap()
    {
        var images = Frontend.MobileProjects.Images;
        byte[] driver = Frontend.Roslyn.Compile("""
            using Xui.Apps.TestApp;
            public static class Program {
                public static int Main() {
                    var metrics = new MobilePerformanceMetrics(new LayoutFrameInstruments());
                    var shell = new MobileTestAppShell(metrics);
                    return shell.Count;
                }
            }
            """, additionalReferences: images.Values.Select(image => MetadataReference.CreateFromImage(image)));
        var assemblies = images.Values.Select(CanvasTests.Read).ToArray();
        using var app = CanvasTests.Read(driver);
        using var runtime = CanvasTests.Read(File.ReadAllBytes(typeof(Xui.Compiler.Runtime.Tasks.Task).Assembly.Location));
        using var framework = new Frontend.Framework(typeof(IServiceProvider).Assembly.GetName().Name + ".dll",
            "System.Text.Encoding.Extensions.dll", "System.Text.Encoding.dll", "System.Threading.Thread.dll", "System.Private.Uri.dll", "System.IO.Pipelines.dll", "System.Threading.dll", "System.Buffers.dll", "System.Memory.dll", "System.IO.Compression.dll", "System.Text.Json.dll", "System.Text.Encodings.Web.dll", "System.Private.Xml.Linq.dll", "System.Private.Xml.dll", "System.Xml.XDocument.dll", "System.Linq.dll", "System.Collections.dll", "System.Collections.NonGeneric.dll");
        try
        {
            _ = new Xui.Compiler.XuiNet.Compilation([app, runtime, .. assemblies, .. framework.Assemblies],
                [.. Xui.Compiler.WASM.Runtime.BrowserNativeMemory.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserJson.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Text.Json"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserStringBuilder.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserEncoding.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserConfiguration.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserTasks.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserResources.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"),
                     framework.Assemblies.Single(a => a.Identity.Name == "System.IO.Compression"), runtime),
                 .. Xui.Compiler.WASM.Runtime.BrowserWeakReferences.Replacements(framework.Assemblies.Single(a => a.Identity.Name == "System.Private.CoreLib"), runtime)]);
            var error = Assert.Throws<NotSupportedException>(() => new WasmEmitter().Emit(app));

            string path = error.Data["Xui.DependencyPath"]?.ToString() ?? "";
            output.WriteLine(error.Message + "\n" + path);
            Assert.Contains("Reference CompareExchange on strings requires managed string identity", error.Message);
            Assert.Contains("System.TimeZoneInfo.get_DisplayName", path);
            string frameworkInputs = string.Join(", ", framework.Assemblies.Select(assembly => $"`{assembly.Identity.Name}`"));
            string projects = string.Join("\n", images.Keys.Select(name => $"- `{name}`"));
            Snapshot.AssertMatches("MobileShellReadiness", $"# Full TestApp mobile shell: compiler readiness\n\nStatus: **WASM not emitted.** This is an expected-unsupported regression, not an execution test.\n\n## Inputs\n\nThe complete repository sources are compiled into separate PEs. TestApp uses its production shader generator; desktop startup and Platform.cs are excluded so the fixture can select the mobile shell directly. Core/emulator use the documented Canvas compiler profile.\n\n{projects}\n\nFramework implementation PEs: {frameworkInputs}.\n\n## Entry\n\n```csharp\nvar metrics = new MobilePerformanceMetrics(new LayoutFrameInstruments());\nvar shell = new MobileTestAppShell(metrics);\nreturn shell.Count;\n```\n\n## Compiler failure\n\n```text\n{error.Message}\n```\n\n## Dependency path\n\n```text\n{path}\n```\n\nGenerated event subscriptions and TimeSpan factories now pass dependency discovery. Duration conversion emits WASM tick arithmetic with managed NaN/range failures and English messages, without retaining System.SR or ResourceManager for those guards. The rating panel's string interpolation now uses mutable UTF-16 GC buffers and integer formatting without retaining the BCL handler body. Closed generic interface methods now specialize their implementations and use distinct dispatch slots, including the demo navigation call. Default string/scalar equality now specializes without BCL factories. Class default equality and array search now preserve identity and virtual Equals overrides. Single-agent volatile field access now passes. The probe supplies the actual XML implementation assemblies and passes rectangular array signatures, missing-constructor failures and single-agent Monitor operations. Compression and JSON implementation assemblies are supplied for the GPU Floorplan loader. The explicit browser task/Lazy runtime now passes CLR scheduler dependencies; closed generic class-virtual dispatch now passes LINQ Select. The probe supplies Memory, Buffers, Threading, Pipelines dependencies. The browser resource profile now supplies original embedded TestApp resources and primitive stream reads, with gzip preparation in the host; the real atlas passes a full-byte CLR/WASM checksum comparison. Neutral XML messages are read from the supplied PE at compile time. Single-agent CurrentManagedThreadId now supports generated XML iterators. Virtual Object.ToString now preserves strings, boxed primitives/enums, array identities and class overrides. Default IEquatable class comparison now dispatches through the selected interface implementation, and Type descriptors support identity hashing for record equality contracts. Primitive Buffer.BlockCopy now preserves byte offsets, overlap and floating-point bit patterns. XML namespace caching now uses WeakRef-backed managed weak references; the Thread facade is supplied. Value-type GetHashCode overrides and tuple hash composition now pass discovery, with a browser-provided HashCode seed. Explicit ordinal string searches now pass the SVG syntax checks. Encoding fallback exception catches now pass JSON UTF-8 discovery. Ordinary Object.GetHashCode now preserves virtual overrides, scalar boxes and stable identity hashes. Unpinned GC array factories now allocate ordinary WASM GC vectors. The SVG transform scanner now preserves the old matcher without a regex engine. Checked integer add/subtract, AppContext switches and array collection/enumeration adapters now execute real LINQ tuple materialization. Repeated-character construction now preserves UTF-16 code units using packed GC arrays. Exact-element array slicing now bypasses the reflection allocation branch while preserving null failures; typed buffer copies retain owners and copy reference fields safely. Reference Interlocked.Exchange now supports JSON metadata disposal without CLR atomics. The encoding facade assemblies and explicit managed-span UTF-8 profile now pass JSON UTF-8 transcoding without pinned locals. MissingManifestResourceException now supports managed catches, hierarchy, messages and inner identity. Stream.ReadAtLeast now preserves short reads, minimum-count validation and optional EOF failure. XML exceptions now preserve messages, source positions and inner identity through typed catches. Monitor references through the Threading facade now retain the existing single-agent lock semantics. Default-comparer acquisition now defers operation checks; hash-only Rect use and array identity hashing/equality pass. Default hashing now reads primitive struct fields without padding bytes, covering AffineTransform. Proven null-format Int32 calls and invariant NumberFormatInfo pairs now pass XML integer/floating conversion. Invariant Decimal formatting now preserves all 96 coefficient bits and scale through native JavaScript strings. All signed/unsigned integer widths now use exact invariant native-string formatting. Built-in exception text now preserves names, messages and inner chains without CLR string allocation; PlatformNotSupportedException has a managed payload. The explicit browser JSON profile now reads the GPU metadata DOM without retaining the BCL parser. Invariant SVG coordinate and hexadecimal color parsing now uses native strings with managed errors. Constrained class/object/array hashing now loads managed receivers and preserves virtual overrides. Ordinal string/character replacement now preserves UTF-16 and literal replacement text. The explicit unmanaged allocator now provides reusable linear buffers and managed allocation failures; the non-generic collection implementation PE is supplied. Managed-span UTF-16 conversion now supports both byte orders, BOMs and strict/replacement fallback. Stateful Unicode decoders now retain partial input, preserve counting state, flush and reset. Character-array string constructors copy UTF-16 with managed range checks. The Unicode encoding-name lookup now supports canonical UTF-8/UTF-16 names and Unicode aliases. Ordinal and ordinal-ignore-case String.Equals now use native strings with simple Unicode casing. Single-agent Thread/Interlocked memory barriers now preserve sequential execution without retaining CLR threads. Generated record formatting now uses a bounded execution-depth guard with managed unwinding. The explicit StringBuilder profile now uses a mutable GC character buffer and native string snapshots. Rect now exposes its existing typed equality through IEquatable, allowing the Floorplan region comparer to specialize. UriFormatException now preserves typed catches and its FormatException hierarchy. Formatted integer interpolation now shares the native numeric formatter, including width-correct hexadecimal character diagnostics. The next failure is reference CompareExchange on native strings in the BCL local-timezone path reached by XML value conversion. Full-shell async startup, DOM composition and GPU execution remain separate dependencies; this probe does not claim that the full application executes.\n\n## WAT\n\nNot emitted.\n");
        }
        finally { foreach (var assembly in assemblies) assembly.Dispose(); }
    }
}
